"""ஓத்து 4 — புணரியல் (எழு. 103–142): காண்டிகை (ஏது, எடுத்துக்காட்டு — 648) + உரை (645, 649, 650).
எடுத்துக்காட்டுகள் நூலின் சொந்தப் புணர்ந்த வடிவங்கள் மட்டும்; எண்ணிக்கைகள் 1602 நூற்பாப் பாடத்தில் (ஏறக்குறைய).
"""
Q = lambda t, f: {"text": t, "from": f}


def R(iy, vagai, text, thunivu="நூலில் நேரடியாக.", vil=None, mar=None):
    d = {"iyaipu": iy, "vagai": vagai, "text": text, "thunivu": thunivu}
    if vil:
        d["vilakkukkuriyathu"] = vil
    if mar:
        d["maruthalai"] = mar
    return d


